    NivelClube(BigDecimal percentualCredito, boolean freteGratis, BigDecimal brindeAcimaDe) {
        this.percentualCredito = percentualCredito;
        this.freteGratis = freteGratis;
        this.brindeAcimaDe = brindeAcimaDe;
    }

